const FOUNTAIN_MIN_CHARGES = 2;
const FOUNTAIN_MAX_CHARGES = 4;
const FOUNTAIN_COOLDOWN_MIN = 201;
const FOUNTAIN_COOLDOWN_MAX = 259;
