import { assertEquals } from "jsr:@std/assert";
import { World } from "../src/lib/ecs-js/index.js";
import { DoorKey } from "../src/rules/components/DoorKey.js";
import { DungeonEntrance } from "../src/rules/components/DungeonEntrance.js";
