function simpleItemArchetypes() {
  if (_SIMPLE_ITEM_ARCHETYPES) return _SIMPLE_ITEM_ARCHETYPES;
  _SIMPLE_ITEM_ARCHETYPES = {
    'gold': GoldStack,
